def solve():
    fixed_seq = {4: -1, 12: 1, 13: -1}
    fixed_c = {1: -1, 2: 0, 7: -3}
    n = 19

    # Generate all possible sequences of length 19 respecting fixed_seq
    import itertools

    free_indices = [i for i in range(n) if i not in fixed_seq]

    for vals in itertools.product([-1, 1], repeat=len(free_indices)):
        seq = [0] * n
        for i, val in zip(free_indices, vals):
            seq[i] = val
        for i, val in fixed_seq.items():
            seq[i] = val

        # Calculate C_k
        C = [0] * n
        for k in range(1, n):
            C[k] = sum(seq[i] * seq[i+k] for i in range(n-k))

        # Check fixed C_k
        valid = True
        for k, val in fixed_c.items():
            if C[k] != val:
                valid = False
                break
        if not valid:
            continue

        # Check sum of C_k^2
        energy = sum(C[k]**2 for k in range(1, n))
        if energy <= 46:
            print("Found:", seq)
            print("Energy:", energy)
            print("C:", C[1:])
            return seq

    print("UNSATISFIABLE")

solve()

