    code = """
#include <stdio.h>

int main() {
    int n = 19;
    int min_energy = 1000000;
    for (int i = 0; i < (1 << 19); i++) {
        int seq[19];
        for (int j = 0; j < 19; j++) {
            seq[j] = (i & (1 << j)) ? 1 : -1;
        }

