            }
            C[k] = sum;
        }

        if (C[1] != -1 || C[2] != 0 || C[7] != -3) continue;

        int energy = 0;
        for (int k = 1; k < 19; k++) {
            energy += C[k] * C[k];
        }

        if (energy <= 46) {
            printf("Found: ");
            for (int j = 0; j < 19; j++) printf("%d ", seq[j]);
            printf("\\nEnergy: %d\\n", energy);
            return 0;
        }
    }
    printf("UNSATISFIABLE\\n");
    return 0;
}
